assignments.value:
={{ 
  ($json.risk_inactivity || $json.risk_nps || $json.risk_support || $json.risk_renewal)
  ? [
      $json.risk_inactivity ? `Aucune connexion depuis ${$json.days_since_login} jours` : null,
      $json.risk_nps ? `NPS de ${$json.nps} inférieur à 7` : null,
      $json.risk_support ? 'Support escaladé' : null,
      $json.risk_renewal ? `Renouvellement dans ${$json.days_until_renewal} jours` : null
    ].filter(Boolean).join(' | ')
  : 'Client sain'
}}

={{ `client_id: ${$json.client_id}
company_name: ${$json.company_name}
days_since_login: ${$json.days_since_login}
nps: ${$json.nps}
support_escalated: ${$json.support_escalated}
days_until_renewal: ${$json.days_until_renewal}
risk_inactivity: ${$json.risk_inactivity}
risk_nps: ${$json.risk_nps}
risk_support: ${$json.risk_support}
risk_renewal: ${$json.risk_renewal}` }}

